record.field:
# Cleanup orphan VPA report actions that don't have a corresponding template
# This fixes duplicate entries in Print menu

VPATemplate = env['vpa.document.template']

# Find all VPA report actions
orphan_reports = env['ir.actions.report'].search([
    ('report_name', 'like', 'vpa_document_layout.report_template_%')
])

# Get all template IDs that have report actions
template_report_ids = VPATemplate.search([]).mapped('report_action_id').ids

# Find and delete orphan reports
orphan_count = 0
for report in orphan_reports:
    if report.id not in template_report_ids:
        report.unlink()
        orphan_count += 1

if orphan_count:
    action = {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {
            'title': 'Cleanup Complete',
            'message': f'Removed {orphan_count} orphan report action(s) from the print menu.',
            'type': 'success',
            'sticky': False,
        }
    }
else:
    action = {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {
            'title': 'No Orphans Found',
            'message': 'No orphan VPA report actions found. Print menu is clean.',
            'type': 'info',
            'sticky': False,
        }
    }
